style.css:
:root,
html,
body {
  /* main accent (buttons, send arrow, highlights) */
  --accent-main-000: #93c5fd;
  --accent-main-100: #3b82f6;
  --accent-main-200: #2563eb;
  --accent-main-900: #0f2547;

  /* secondary accents */
  --accent-secondary-000: #bfdbfe;
  --accent-secondary-100: #60a5fa;
  --accent-secondary-200: #3b82f6;
  --accent-secondary-900: #10243f;

  /* the "Pro"/upgrade accent, usually a different orange */
  --accent-pro-000: #a5b4fc;
  --accent-pro-100: #6366f1;
  --accent-pro-200: #4f46e5;
  --accent-pro-900: #1e1b4b;
}

/* catch stray oranges that aren't variable-driven */
[class*="text-accent"],
a {
  color: #60a5fa !important;
}

svg[class*="text-accent"] path {
  fill: currentColor !important;
}
